const dateKey = (date = new Date()) => new Intl.DateTimeFormat("en-CA", { timeZone: "America/Sao_Paulo", year: "numeric", month: "2-digit", day: "2-digit" }).format(date);
const today = () => dateKey();
const shiftDate = (base, days) => { const date = new Date(`${base}T12:00:00-03:00`); date.setDate(date.getDate() + days); return dateKey(date); };
const photoData = (file) => new Promise((resolve, reject) => { const reader = new FileReader(); reader.onerror = reject; reader.onload = () => { const image = new Image(); image.onerror = reject; image.onload = () => { const scale = Math.min(1, 900 / Math.max(image.width, image.height)), canvas = document.createElement("canvas"); canvas.width = Math.round(image.width * scale); canvas.height = Math.round(image.height * scale); canvas.getContext("2d").drawImage(image, 0, 0, canvas.width, canvas.height); resolve(canvas.toDataURL("image/jpeg", .65)); }; image.src = reader.result; }; reader.readAsDataURL(file); });
const ocrPhotoData = (file) => new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const image=new Image();image.onerror=reject;image.onload=()=>{const scale=Math.min(1,2400/Math.max(image.width,image.height)),canvas=document.createElement("canvas");canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext("2d").drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL("image/jpeg",.94))};image.src=reader.result};reader.readAsDataURL(file)});
const documentData = (file) => new Promise((resolve, reject) => { if (file.size > 2 * 1024 * 1024) return reject(new Error("too-large")); const reader = new FileReader(); reader.onerror = reject; reader.onload = () => resolve({ name:file.name, type:file.type, size:file.size, data:reader.result, uploadedAt:new Date().toISOString() }); reader.readAsDataURL(file); });
const meterCrops = (source) => new Promise((resolve,reject)=>{const image=new Image();image.onerror=reject;image.onload=()=>{const regions=[[.34,.315,.40,.09],[.30,.28,.48,.14],[.24,.22,.58,.24]],variants=[];for(const [x,y,w,h] of regions){for(const threshold of [null,150,185]){const canvas=document.createElement("canvas"),scale=5;canvas.width=Math.round(image.width*w*scale);canvas.height=Math.round(image.height*h*scale);const context=canvas.getContext("2d");context.imageSmoothingEnabled=true;context.drawImage(image,image.width*x,image.height*y,image.width*w,image.height*h,0,0,canvas.width,canvas.height);const pixels=context.getImageData(0,0,canvas.width,canvas.height);for(let index=0;index<pixels.data.length;index+=4){const gray=pixels.data[index]*.299+pixels.data[index+1]*.587+pixels.data[index+2]*.114,value=threshold===null?Math.max(0,Math.min(255,(gray-128)*1.65+128)):gray>threshold?255:0;pixels.data[index]=pixels.data[index+1]=pixels.data[index+2]=value}context.putImageData(pixels,0,0);variants.push(canvas.toDataURL("image/png"))}}resolve(variants)};image.src=source});
const readMeterPhoto = async (image, previous = 0) => {
  const module=await import("tesseract.js"),api=module.default||module,worker=await api.createWorker("eng",1,{logger:()=>{}}),variants=await meterCrops(image),results=[];
  try{await worker.setParameters({tessedit_char_whitelist:"0123456789",tessedit_pageseg_mode:api.PSM.SINGLE_LINE,preserve_interword_spaces:"0"});for(const variant of variants){const result=await worker.recognize(variant),digits=(result.data.text||"").replace(/\D/g,"");if(digits.length>=4&&digits.length<=9)results.push({digits,number:Number(digits),confidence:Math.round(result.data.confidence||0)})}if(!results.length){await worker.setParameters({tessedit_pageseg_mode:api.PSM.SPARSE_TEXT});const fallback=await worker.recognize(image),groups=(fallback.data.text||"").match(/\d[\d\s]{3,10}\d/g)||[];for(const group of groups){const digits=group.replace(/\D/g,"");if(digits.length>=4&&digits.length<=9)results.push({digits,number:Number(digits),confidence:Math.round(fallback.data.confidence||0)})}}}finally{await worker.terminate()}
  const valid=results.filter((item)=>item.number>=Number(previous)),selected=(valid.length?valid:results).sort((a,b)=>((b.digits.length===6?25:0)+b.confidence)-((a.digits.length===6?25:0)+a.confidence))[0];
  if(!selected)throw new Error("no-reading");
  return {value:String(selected.number),display:selected.digits,confidence:selected.confidence};
};
