export default function App() {
  const [session, setSession] = useState(undefined);
  const [passwordRecovery, setPasswordRecovery] = useState(() => typeof window !== "undefined" && window.location.hash.includes("type=recovery"));
  const [data, setData] = useState(initialData);
  const [page, setPage] = useState("inicio");
  const [modal, setModal] = useState(null);
  const [toast, setToast] = useState("");
  const [menu, setMenu] = useState(false);
  useEffect(() => {
    if (!supabaseConfigured) { setSession(null); return; }
    supabase.auth.getSession().then(({ data: authData }) => setSession(authData.session));
    const { data: listener } = supabase.auth.onAuthStateChange((event, nextSession) => { setSession(nextSession); if (event === "PASSWORD_RECOVERY") setPasswordRecovery(true); });
    return () => listener.subscription.unsubscribe();
  }, []);
  useEffect(() => { try { const current = JSON.parse(localStorage.getItem("agua-rural-v8")); if (current?.grants) return setData(current); const previous = JSON.parse(localStorage.getItem("agua-rural-v7")); if (previous?.grants) setData({ ...previous, readings: [] }); } catch {} }, []);
  useEffect(() => { try { localStorage.setItem("agua-rural-v8", JSON.stringify(data)); } catch { setToast("O armazenamento de fotos está cheio. Tente uma imagem menor."); } }, [data]);
  const go = (id) => { setPage(id); setMenu(false); };
  if (session === undefined) return <div className="auth-loading"><img src="/agua-rural-logo.png" alt="Água Rural" /><span>Preparando acesso seguro...</span></div>;
  if (passwordRecovery && session) return <UpdatePasswordScreen onComplete={() => setPasswordRecovery(false)} />;
  const previewSession = process.env.NODE_ENV === "development" && !session && typeof window !== "undefined" && window.location.search === "?preview=mobile";
  if (!session && !previewSession) return <LoginScreen />;
  const activeUser = session?.user || { email: "demonstracao@local", user_metadata: { full_name: "Prévia local" } };
  const userName = activeUser.user_metadata?.full_name || activeUser.email?.split("@")[0] || "Usuário";
  const userRole = activeUser.user_metadata?.role === "operator" ? "Operador" : "Administrador";
  const initials = userName.split(/\s+/).slice(0, 2).map((part) => part[0]).join("").toUpperCase();
  const logout = async () => { await supabase.auth.signOut(); setMenu(false); };
  const saveReading = (reading) => { setData((d) => ({ ...d, readings: [reading, ...d.readings] })); setModal(null); setToast(reading.status === "divergente" ? "Leitura salva e enviada para conferência." : "Leitura salva com sucesso."); setPage("inicio"); };
  const saveGrant = (grant, property) => { setData((d) => ({ properties: property ? [...d.properties, property] : d.properties, grants: [...d.grants, grant], readings: d.readings })); setModal(null); setToast("Outorga cadastrada com sucesso."); };
  const saveGrantDocument = (grantId, document) => { setData((d) => ({ ...d, grants:d.grants.map((grant) => grant.id === grantId ? { ...grant, document } : grant) })); setToast("Documento da outorga anexado com sucesso."); };
  return <div className="app-shell">
    <aside className={menu ? "sidebar open" : "sidebar"}>
      <div className="brand"><img src="/agua-rural-logo.png" alt="Água Rural" /><span className="brand-tagline">Controle e gestão da água no campo</span><button onClick={() => setMenu(false)} aria-label="Fechar menu"><X /></button></div>
      <nav>{nav.map(([id, label, Icon]) => <button key={id} className={page === id ? "active" : ""} onClick={() => go(id)}><Icon />{label}</button>)}</nav>
      <div className="support"><ShieldCheck /><div><strong>Sessão protegida</strong><span>Usuário autenticado</span></div></div>
      <div className="profile"><div>{initials}</div><span><strong>{userName}</strong><small>{userRole} · FORTE GRÃOS</small></span><button className="logout" onClick={logout} aria-label="Sair do aplicativo" title="Sair"><LogOut /><span>Sair</span></button></div>
    </aside>
    <main>
      <header className="topbar"><button className="menu" aria-label="Abrir menu" onClick={() => setMenu(true)}><Menu /></button><div><span>Gestão hídrica</span><h1>{nav.find((n) => n[0] === page)?.[1]}</h1></div><div className="header-date"><Clock3 /><span><small>Hoje</small><strong>{new Date().toLocaleDateString("pt-BR", { day: "2-digit", month: "long" })}</strong></span></div></header>
      <div className="content">
        {page === "inicio" && <Dashboard data={data} onReading={(id) => setModal({ type: "reading", id })} onPage={go} />}
        {page === "leituras" && <Readings data={data} onReading={(id) => setModal({ type: "reading", id })} />}
        {page === "outorgas" && <GrantsPanel data={data} onNew={() => setModal({ type: "grant" })} onReading={(id) => setModal({ type: "reading", id })} onDocument={saveGrantDocument} onError={setToast} />}
        {page === "relatorios" && <Reports data={data} userName={userName} />}
      </div>
    </main>
    <div className="mobile-nav">{nav.map(([id, label, Icon]) => <button key={id} className={page === id ? "active" : ""} onClick={() => go(id)}><Icon /><span>{label}</span></button>)}</div>
    {modal?.type === "reading" && <OperatorReadingModal data={data} initialId={modal.id} userName={userName} onClose={() => setModal(null)} onSave={saveReading} />}
    {modal?.type === "grant" && <GrantModal data={data} onClose={() => setModal(null)} onSave={saveGrant} />}
    {toast && <div className="toast"><CheckCircle2 />{toast}<button onClick={() => setToast("")}><X /></button></div>}
  </div>;
}

function LoginScreen() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);
  const login = async (event) => {
    event.preventDefault();
    if (!supabaseConfigured) { setError("A autenticação ainda não foi conectada ao ambiente publicado."); return; }
    setLoading(true); setError(""); setMessage("");
    const { error: authError } = await supabase.auth.signInWithPassword({ email: email.trim(), password });
    if (authError) setError("E-mail ou senha inválidos.");
    setLoading(false);
  };
  const resetPassword = async () => {
    if (!email.trim()) { setError("Informe seu e-mail para recuperar a senha."); return; }
    setLoading(true); setError("");
    const { error: resetError } = await supabase.auth.resetPasswordForEmail(email.trim(), { redirectTo: window.location.origin });
    if (resetError) setError("Não foi possível enviar a recuperação agora.");
    else setMessage("Enviamos as instruções de recuperação para o seu e-mail.");
    setLoading(false);
  };
  return <main className="auth-page"><section className="auth-panel"><div className="auth-brand"><img src="/agua-rural-logo.png" alt="Água Rural" /><span>Controle e gestão da água no campo</span></div><div className="auth-copy"><span className="eyebrow">ACESSO RESTRITO</span><h1>Entre no Água Rural</h1><p>Use as credenciais autorizadas pela Forte Grãos.</p></div><form onSubmit={login}><label>E-mail<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} autoComplete="email" required placeholder="seu@email.com" /></label><label>Senha<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} autoComplete="current-password" required placeholder="Sua senha" /></label>{error && <div className="auth-error"><AlertTriangle />{error}</div>}{message && <div className="auth-message"><CheckCircle2 />{message}</div>}<button className="primary auth-submit" type="submit" disabled={loading}>{loading ? "Entrando..." : "Entrar"}</button><button className="auth-reset" type="button" onClick={resetPassword} disabled={loading}>Esqueci minha senha</button></form><footer><ShieldCheck /><span>Conexão protegida e acesso individual</span></footer></section><aside className="auth-visual"><Droplets /><h2>Gestão hídrica com histórico confiável.</h2><p>Leituras, evidências e indicadores reunidos em um ambiente seguro.</p></aside></main>;
}

function UpdatePasswordScreen({ onComplete }) {
  const [password, setPassword] = useState("");
  const [confirmation, setConfirmation] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const updatePassword = async (event) => {
    event.preventDefault(); setError("");
    if (password.length < 8) return setError("A nova senha deve ter pelo menos 8 caracteres.");
    if (password !== confirmation) return setError("As senhas informadas não são iguais.");
    setLoading(true);
    const { error: updateError } = await supabase.auth.updateUser({ password });
    setLoading(false);
    if (updateError) return setError("Não foi possível atualizar a senha. Solicite um novo link de recuperação.");
    onComplete();
  };
  return <main className="auth-page"><section className="auth-panel"><div className="auth-brand"><img src="/agua-rural-logo.png" alt="Água Rural" /><span>Controle e gestão da água no campo</span></div><div className="auth-copy"><span className="eyebrow">NOVA SENHA</span><h1>Atualize sua senha</h1><p>Crie uma senha segura para acessar o Água Rural.</p></div><form onSubmit={updatePassword}><label>Nova senha<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} autoComplete="new-password" minLength="8" required placeholder="Mínimo de 8 caracteres" /></label><label>Confirmar nova senha<input type="password" value={confirmation} onChange={(event) => setConfirmation(event.target.value)} autoComplete="new-password" minLength="8" required placeholder="Repita a nova senha" /></label>{error && <div className="auth-error"><AlertTriangle />{error}</div>}<button className="primary auth-submit" type="submit" disabled={loading}>{loading ? "Atualizando..." : "Salvar nova senha"}</button></form><footer><ShieldCheck /><span>Após salvar, você entrará automaticamente no aplicativo</span></footer></section><aside className="auth-visual"><ShieldCheck /><h2>Seu acesso, agora protegido por uma nova senha.</h2><p>A senha é atualizada diretamente no ambiente seguro de autenticação.</p></aside></main>;
}

function Dashboard({ data, onReading, onPage }) {
  const todays = data.readings.filter((r) => r.date === today());
  const pending = data.grants.filter((g) => g.status === "ativa" && !todays.some((r) => r.grantId === g.id));
  const yesterdayKey=shiftDate(today(),-1), last7Start=shiftDate(today(),-7);
  const yesterday=data.readings.filter(r=>r.date===yesterdayKey), last7=data.readings.filter(r=>r.date>=last7Start&&r.date<=yesterdayKey);
  const sum=(rows,key)=>rows.reduce((s,r)=>s+Number(r[key]||0),0), water=sum(yesterday,"consumption"), hours=sum(yesterday,"hours"), avgFlow=hours?water/hours:0;
  const expiring=data.grants.filter(g=>{const days=(new Date(`${g.validity}T12:00:00`)-new Date())/86400000;return days>=0&&days<=180});
  const divergent=data.readings.filter(r=>r.status==="divergente"), efficiency=operationalEfficiency(data);
  return <div className="stack">
    <section className="welcome compact-welcome"><div><span className="eyebrow">GESTÃO DA IRRIGAÇÃO</span><h2>Visão operacional</h2><p>Fechamentos, pendências e alertas em um só lugar.</p></div><button className="primary" disabled={!pending.length} onClick={() => pending[0]&&onReading(pending[0].id)}>{pending.length?<><Plus/> Registrar leitura</>:<><CheckCircle2/> Dia concluído</>}</button></section>
    <section className={pending.length?"mobile-reading-focus has-pending":"mobile-reading-focus complete"}><div className="mobile-focus-heading"><div className="mobile-focus-icon">{pending.length?<Droplets/>:<CheckCircle2/>}</div><div><span className="mobile-focus-label">LEITURAS DE HOJE</span><h3>{pending.length?"Escolha o equipamento":"Leituras concluídas"}</h3></div></div>{pending.length?<><p className="mobile-choice-help">Toque no equipamento onde deseja iniciar a leitura.</p><div className="mobile-reading-options">{pending.map(g=>{const property=data.properties.find(p=>p.id===g.propertyId);return <button key={g.id} onClick={()=>onReading(g.id)}><span><strong>{g.name}</strong><small>{property?.name}</small></span><ChevronRight/></button>})}</div></>:<p className="mobile-complete-message"><strong>Trabalho finalizado</strong><small>{todays.length} de {data.grants.length} leituras realizadas hoje</small></p>}<div className="mobile-day-progress"><span><b>{todays.length}</b> realizadas</span><span><b>{pending.length}</b> pendentes</span></div></section>
    <section className="admin-command-center">
      <div className="admin-today-card"><div className="admin-today-copy"><span>OPERAÇÃO DE HOJE</span><h3>{pending.length?`${pending.length} leituras aguardando registro`:"Todas as leituras foram concluídas"}</h3><p>{pending.length?"Acompanhe o avanço da equipe e os pontos que ainda precisam de medição.":"A operação diária está completa e pronta para conferência."}</p><button disabled={!pending.length} onClick={()=>pending[0]&&onReading(pending[0].id)}>{pending.length?<><Plus/>Registrar uma leitura</>:<><CheckCircle2/>Dia concluído</>}</button></div><div className="admin-progress-score"><strong>{todays.length}<small>/{data.grants.length}</small></strong><span>leituras realizadas</span><div><i style={{width:`${(todays.length/Math.max(data.grants.length,1))*100}%`}}/></div><small>{Math.round((todays.length/Math.max(data.grants.length,1))*100)}% concluído</small></div></div>
      <div className="admin-key-metrics"><article><div className="admin-metric-icon water"><Droplets/></div><span>Consumo de ontem</span><strong>{fmt(water,0)} m³</strong><small>{yesterday.length?`${fmt(hours)} h de funcionamento`:"Sem fechamento disponível"}</small></article><article><div className="admin-metric-icon warning"><AlertTriangle/></div><span>Inconsistências</span><strong>{divergent.length}</strong><small>{divergent.length?"Precisam de conferência":"Nenhuma divergência encontrada"}</small></article><article><div className="admin-metric-icon document"><FileText/></div><span>Outorgas a vencer</span><strong>{expiring.length}</strong><small>Nos próximos 180 dias</small></article></div>
      <div className="admin-operation-grid"><section className="admin-equipment-panel"><header><div><span>ACOMPANHAMENTO</span><h3>Equipamentos de hoje</h3></div><button onClick={()=>onPage("leituras")}>Abrir histórico <ChevronRight/></button></header><div className="admin-equipment-list">{data.grants.map(g=>{const reading=todays.find(r=>r.grantId===g.id),property=data.properties.find(p=>p.id===g.propertyId);return <article key={g.id}><div className={reading?"equipment-state done":"equipment-state pending"}>{reading?<CheckCircle2/>:<Clock3/>}</div><div className="equipment-name"><strong>{g.name}</strong><span>{property?.name}</span></div><div className="equipment-result"><span>{reading?"Registrado hoje":"Aguardando leitura"}</span><strong>{reading?`${fmt(reading.consumption,0)} m³`:"Pendente"}</strong></div><Status value={reading?reading.status:"pendente"}/></article>})}</div></section><aside className="admin-attention-panel"><header><span>ATENÇÃO</span><h3>O que precisa de ação</h3></header><div className={pending.length?"attention-main urgent":"attention-main clear"}>{pending.length?<Clock3/>:<CheckCircle2/>}<strong>{pending.length?`${pending.length} leituras pendentes`:"Nenhuma pendência"}</strong><p>{pending.length?"Ainda existem equipamentos sem registro no dia.":"Todos os equipamentos foram registrados."}</p></div><dl><div><dt>Inconsistências</dt><dd>{divergent.length}</dd></div><div><dt>Próximos vencimentos</dt><dd>{expiring.length}</dd></div><div><dt>Eficiência operacional</dt><dd>{efficiency.score}%</dd></div></dl><button onClick={()=>onPage("relatorios")}>Ver relatório completo <ChevronRight/></button></aside></div>
    </section>
    <section className="indicator-focus">
      <section className={`closing-summary ${yesterday.length?"is-closed":"is-waiting"}`}><div className="closing-main"><span>Último fechamento · {brDate(yesterdayKey)}</span><small>{yesterday.length?"Período concluído":"Aguardando leitura do período"}</small><strong>{yesterday.length?fmt(water,0):"—"} {!!yesterday.length&&<b>m³</b>}</strong><p>{yesterday.length?"Consumo de água de ontem":"O indicador será calculado após o registro"}</p></div><div className="closing-details"><div><Clock3/><span>Funcionamento</span><strong>{yesterday.length?`${fmt(hours)} h`:"—"}</strong></div><div><Gauge/><span>Vazão média</span><strong>{yesterday.length?`${fmt(avgFlow)} m³/h`:"—"}</strong></div></div></section>
      <section className={pending.length?"daily-pending has-pending":"daily-pending complete"}><div className="pending-icon">{pending.length?<Clock3/>:<CheckCircle2/>}</div><div className="pending-copy"><span>Leituras de hoje</span><strong>{pending.length?`${pending.length} ${pending.length===1?"leitura pendente":"leituras pendentes"}`:"Todas as leituras concluídas"}</strong><small>{pending.length?pending.map(g=>g.name).join(" · "):`${todays.length} de ${data.grants.length} outorgas registradas`}</small></div><div className="pending-progress"><strong>{todays.length}/{data.grants.length}</strong><span>realizadas</span></div></section>
      <div className="secondary-indicators">
        <Metric icon={TrendingUp} tone="green" label="Últimos 7 dias" value={`${fmt(sum(last7,"consumption"),0)} m³`} note={`${fmt(sum(last7,"hours"))} h de funcionamento`} />
        <Metric icon={FileText} tone="green" label="Próximos vencimentos" value={expiring.length} note="Em até 180 dias" />
        <Metric icon={AlertTriangle} tone="amber" label="Inconsistências" value={divergent.length} note="Exigem conferência" />
        <article className="metric efficiency-card"><div className="efficiency-ring" style={{"--score":`${efficiency.score*3.6}deg`}}><strong>{efficiency.score}%</strong></div><span>Eficiência operacional</span><b>{efficiency.label}</b><small>Qualidade dos registros</small></article>
      </div>
    </section>
    <WaterConsumptionChart readings={data.readings} />
    <div className="dashboard-grid"><section className="panel"><div className="panel-title"><div><h3>Leituras de hoje</h3><p>Acompanhe o status por outorga</p></div><button className="link" onClick={() => onPage("leituras")}>Ver todas <ChevronRight /></button></div>
      <div className="grant-list">{data.grants.map((g) => { const r = todays.find((x) => x.grantId === g.id); const prop = data.properties.find((p) => p.id === g.propertyId); return <article key={g.id} className="grant-row"><div className="equip"><Gauge /></div><div className="grow"><strong>{g.name}</strong><span>{prop?.name} · {g.number}</span></div>{r ? <><div className="reading-stat"><span>Consumo</span><strong>{fmt(r.consumption, 0)} m³</strong></div><div className="reading-stat"><span>Funcionamento</span><strong>{fmt(r.hours)} h</strong></div><Status value={r.status} /></> : <><div className="last"><span>Última leitura</span><strong>{brDate(lastReading(data, g.id)?.date || today())}</strong></div><Status value="pendente" /></>}</article>; })}</div>
    </section><aside className="side-stack"><section className="panel alert-panel"><div className="panel-title"><div><h3>Alertas automáticos</h3><p>Pontos que precisam de atenção</p></div><span className="alert-count">{pending.length+divergent.length+expiring.length}</span></div>{divergent.slice(0,1).map(r=><AlertItem key={r.id} title="Consumo fora da média" text={`${data.grants.find(g=>g.id===r.grantId)?.name} aguarda conferência.`}/>)}{pending.slice(0,1).map(g=><AlertItem key={g.id} title="Leitura pendente" text={`${g.name} ainda não possui leitura hoje.`}/>)}{expiring.slice(0,1).map(g=><AlertItem key={g.id} title="Outorga próxima do vencimento" text={`${g.name} vence em ${brDate(g.validity)}.`}/>)}<button className="full-link" onClick={() => onPage("leituras")}>Ver histórico <ChevronRight /></button></section><section className="tip"><Activity /><div><strong>Eficiência operacional: {efficiency.label}</strong><p>Indicador baseado na regularidade, estabilidade da vazão e inconsistências registradas.</p></div></section></aside></div>
  </div>;
}

function AlertItem({title,text}){return <div className="alert-item"><div><AlertTriangle/></div><span><strong>{title}</strong><p>{text}</p></span></div>}
function operationalEfficiency(data){const active=Math.max(data.grants.filter(g=>g.status==="ativa").length,1),done=data.readings.filter(r=>r.date===today()).length/active,consistent=1-data.readings.filter(r=>r.status==="divergente").length/Math.max(data.readings.length,1);const flows=data.readings.filter(r=>r.hours>0).map(r=>r.consumption/r.hours),mean=flows.reduce((s,v)=>s+v,0)/Math.max(flows.length,1),variation=flows.reduce((s,v)=>s+Math.abs(v-mean),0)/Math.max(flows.length,1),stable=mean?Math.max(0,1-variation/mean):1,score=Math.round((done*.45+stable*.3+consistent*.25)*100);return{score,label:score>=90?"Excelente":score>=75?"Bom":score>=55?"Atenção":"Crítico"}}

function Metric({ icon: Icon, tone, label, value, note }) { return <article className="metric"><div className={`metric-icon ${tone}`}><Icon /></div><span>{label}</span><strong>{value}</strong><small>{note}</small></article>; }
function WaterConsumptionChart({readings}) {
  const dayNames=["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"], periods=Array.from({length:7},(_,i)=>{const key=shiftDate(today(),-7+i),d=new Date(`${key}T12:00:00`);return{label:i===6?"Ontem":dayNames[d.getDay()],date:d.toLocaleDateString("pt-BR",{day:"2-digit",month:"2-digit"}),value:readings.filter(r=>r.date===key).reduce((s,r)=>s+r.consumption,0)}}), values=periods.map(p=>p.value).filter(Boolean), average=values.reduce((s,v)=>s+v,0)/Math.max(values.length,1);
  const level = (value) => !value||value<average*.7 ? "low" : value>average*1.25 ? "high" : "normal";
  return <section className="panel water-chart">
    <div className="panel-title"><div><h3>Consumo nos últimos 7 dias fechados</h3><p>Período encerrado ontem</p></div><div className="water-legend"><span><i className="low" />Baixo</span><span><i className="normal" />Normal</span><span><i className="high" />Alto</span></div></div>
    <div className="drops-chart" role="img" aria-label="Consumo de água dos sete últimos dias encerrados">
      {periods.map((item) => <div className={`drop-column ${level(item.value)}`} key={item.date}>
        <strong>{item.value}<small> m³</small></strong>
        <svg className="water-drop" viewBox="0 0 64 82" aria-hidden="true"><path d="M32 2C26 16 7 36 7 54c0 15 11 26 25 26s25-11 25-26C57 36 38 16 32 2Z" /><path className="shine" d="M19 50c1-7 5-13 10-19" /></svg>
        <span>{item.label}</span><small>{item.date}</small>
      </div>)}
    </div>
  </section>;
}
function Status({ value }) { const labels = { concluida: "Concluída", pendente: "Pendente", divergente: "Divergente", ativa: "Ativa", vencida: "Vencida" }; return <span className={`status ${value}`}>{value === "concluida" && <CheckCircle2 />}{value === "divergente" && <AlertTriangle />}{labels[value] || value}</span>; }
function lastReading(data, id) { return data.readings.filter((r) => r.grantId === id).sort((a,b) => b.date.localeCompare(a.date))[0]; }

function Readings({ data, onReading }) {
  const [search,setSearch]=useState(""),[from,setFrom]=useState(shiftDate(today(),-29)),[to,setTo]=useState(today()),[grant,setGrant]=useState("todos"),[preview,setPreview]=useState(null);
  const nextGrant=data.grants.find(g=>g.status==="ativa"&&!data.readings.some(r=>r.grantId===g.id&&r.date===today()));
  const list=data.readings.filter(r=>{const g=data.grants.find(x=>x.id===r.grantId),text=`${g?.name} ${g?.number} ${r.user} ${r.culture}`.toLowerCase();return(!search||text.includes(search.toLowerCase()))&&(grant==="todos"||r.grantId===grant)&&r.date>=from&&r.date<=to});
  return <div className="stack"><section className="page-head"><div><span className="eyebrow">HISTÓRICO OPERACIONAL</span><h2>Leituras</h2><p>Consulte medições, indicadores e comprovantes.</p></div><button className="primary" disabled={!nextGrant} onClick={() => nextGrant&&onReading(nextGrant.id)}>{nextGrant?<><Plus/> Nova leitura</>:<><CheckCircle2/> Dia concluído</>}</button></section><div className="history-filters"><label className="search-field"><Search/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar outorga, cultura ou usuário"/></label><label>Outorga<select value={grant} onChange={e=>setGrant(e.target.value)}><option value="todos">Todas</option>{data.grants.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select></label><label>De<input type="date" value={from} max={to} onChange={e=>setFrom(e.target.value)}/></label><label>Até<input type="date" value={to} min={from} onChange={e=>setTo(e.target.value)}/></label></div><div className="history-list-new">{list.map(r=>{const g=data.grants.find(x=>x.id===r.grantId),flow=r.hours>0?r.consumption/r.hours:0;return <article className="history-record" key={r.id}><div className="history-date"><strong>{brDate(r.date)}</strong><span>{g?.name}</span><Status value={r.status}/></div><div className="history-values"><div><span>Hidrômetro</span><strong>{fmt(r.waterNow,0)} m³</strong><small>+{fmt(r.consumption,0)} m³</small></div><div><span>Horímetro</span><strong>{fmt(r.hourNow)} h</strong><small>+{fmt(r.hours)} h</small></div><div><span>Vazão média</span><strong>{fmt(flow)} m³/h</strong><small>{r.culture||"Cultura não informada"}</small></div></div><div className="record-proof"><PhotoProof label="Hidrômetro" src={r.photos?.water} onOpen={setPreview}/><PhotoProof label="Horímetro" src={r.photos?.hour} onOpen={setPreview}/><small>{r.user}</small></div></article>})}{!list.length&&<div className="empty-report">Nenhum registro encontrado neste período.</div>}</div>{preview&&<div className="photo-viewer" onClick={()=>setPreview(null)}><button aria-label="Fechar foto"><X/></button><img src={preview} alt="Comprovante da leitura"/></div>}</div>;
}
function PhotoProof({label,src,onOpen}){return src&&typeof src==="string"?<button onClick={()=>onOpen(src)}><img src={src} alt=""/><span>{label}</span></button>:<span className="no-photo"><Camera/> Sem foto</span>}

function Grants({ data, onNew, onReading }) { return <div className="stack"><section className="page-head"><div><span className="eyebrow">CADASTROS</span><h2>Outorgas</h2><p>Equipamentos, limites e documentos em um só lugar.</p></div><button className="primary" onClick={onNew}><Plus /> Nova outorga</button></section><div className="cards-grid">{data.grants.map((g) => { const p=data.properties.find((x)=>x.id===g.propertyId), r=lastReading(data,g.id), doneToday=data.readings.some(x=>x.grantId===g.id&&x.date===today()); return <article className="grant-card" key={g.id}><header><div className="equip"><Droplets/></div><Status value={g.status}/></header><h3>{g.name}</h3><p>{p?.name}</p><dl><div><dt>Número</dt><dd>{g.number}</dd></div><div><dt>Fonte</dt><dd>{g.source}</dd></div><div><dt>Vazão autorizada</dt><dd>{g.flow} m³/h</dd></div><div><dt>Validade</dt><dd>{brDate(g.validity)}</dd></div></dl><div className="card-last"><span>Última leitura</span><strong>{r ? `${fmt(r.waterNow,0)} m³ · ${brDate(r.date)}` : "Sem leituras"}</strong></div><button className="outline full" disabled={doneToday} onClick={() => !doneToday&&onReading(g.id)}>{doneToday?<><CheckCircle2/> Leitura realizada hoje</>:"Registrar leitura"}</button></article>})}</div></div>; }

function GrantsPanel({data,onNew,onReading,onDocument,onError}) {
  const attach=async(grantId,event)=>{const file=event.target.files?.[0];if(!file)return;try{const document=await documentData(file);onDocument(grantId,document)}catch(error){onError(error.message==="too-large"?"O documento deve ter no máximo 2 MB.":"Não foi possível anexar o documento.")}event.target.value=""};
  return <div className="stack"><section className="page-head"><div><span className="eyebrow">CADASTROS</span><h2>Outorgas</h2><p>Equipamentos, limites e documentos de cada área.</p></div><button className="primary" onClick={onNew}><Plus/> Nova outorga</button></section><div className="cards-grid">{data.grants.map((grant)=>{const property=data.properties.find((item)=>item.id===grant.propertyId),reading=lastReading(data,grant.id),doneToday=data.readings.some((item)=>item.grantId===grant.id&&item.date===today());return <article className="grant-card" key={grant.id}><header><div className="equip"><Droplets/></div><Status value={grant.status}/></header><h3>{grant.name}</h3><p>{property?.name}</p><dl><div><dt>Número</dt><dd>{grant.number}</dd></div><div><dt>Fonte</dt><dd>{grant.source}</dd></div><div><dt>Vazão autorizada</dt><dd>{grant.flow} m³/h</dd></div><div><dt>Validade</dt><dd>{brDate(grant.validity)}</dd></div></dl><section className={grant.document?"grant-document attached":"grant-document"}><div className="document-heading"><Paperclip/><div><span>DOCUMENTO DA OUTORGA</span><strong>{grant.document?.name||"Nenhum arquivo anexado"}</strong>{grant.document&&<small>Anexado em {new Date(grant.document.uploadedAt).toLocaleDateString("pt-BR")}</small>}</div></div><div className="document-actions">{grant.document&&<a href={grant.document.data} target="_blank" rel="noreferrer" aria-label={`Visualizar ${grant.document.name}`}><Eye/> Visualizar</a>}<label><Upload/> {grant.document?"Substituir":"Anexar PDF ou foto"}<input type="file" accept="application/pdf,image/*" onChange={(event)=>attach(grant.id,event)}/></label></div><small className="document-limit">PDF, JPG ou PNG · máximo 2 MB</small></section><div className="card-last"><span>Última leitura</span><strong>{reading?`${fmt(reading.waterNow,0)} m³ · ${brDate(reading.date)}`:"Sem leituras"}</strong></div><button className="outline full" disabled={doneToday} onClick={()=>!doneToday&&onReading(grant.id)}>{doneToday?<><CheckCircle2/> Leitura realizada hoje</>:"Registrar leitura"}</button></article>})}</div></div>;
}

function Reports(props) {
  const [step,setStep]=useState(0);
  const stages=[["Painel",BarChart3],["Leituras",Gauge],["Comprovantes",Camera]];
  return <div className={`mobile-report-step step-${step}`}><nav className="report-steps" aria-label="Etapas do relatório">{stages.map(([label,Icon],index)=><button key={label} className={step===index?"active":""} onClick={()=>setStep(index)}><span>{index+1}</span><Icon/><strong>{label}</strong></button>)}</nav><ReportDocument {...props}/><div className="report-step-actions"><button className="outline" disabled={step===0} onClick={()=>setStep(value=>Math.max(0,value-1))}>Voltar</button><button className="primary" disabled={step===2} onClick={()=>setStep(value=>Math.min(2,value+1))}>{step===1?"Ver comprovantes":"Continuar"}<ChevronRight/></button></div></div>;
}

function ReportDocument({ data, userName }) {
  const defaultFrom = new Date(Date.now() - 29 * 86400000).toISOString().slice(0, 10);
  const [grant, setGrant] = useState("todos"), [from, setFrom] = useState(defaultFrom), [to, setTo] = useState(today());
  const rows=data.readings.filter((r)=>(grant==="todos"||r.grantId===grant)&&(!from||r.date>=from)&&(!to||r.date<=to)).sort((a,b)=>b.date.localeCompare(a.date));
  const water=rows.reduce((s,r)=>s+r.consumption,0), hours=rows.reduce((s,r)=>s+r.hours,0), selectedGrant=data.grants.find(g=>g.id===grant), selectedProperty=data.properties.find(p=>p.id===selectedGrant?.propertyId), proofCount=rows.filter(r=>r.photos?.water&&r.photos?.hour).length, photoRows=rows.filter(r=>r.photos?.water||r.photos?.hour);
  const csv=()=>{ const lines=[["Data","Outorga","Cultura","Hidrômetro anterior","Hidrômetro atual","Consumo m3","Horímetro anterior","Horímetro atual","Horas","Vazão média m3/h","Latitude","Longitude","Precisão GPS m","Responsável","Status","Observação"],...rows.map(r=>[r.date,data.grants.find(g=>g.id===r.grantId)?.name,r.culture||"Não informada",r.waterPrev,r.waterNow,r.consumption,r.hourPrev,r.hourNow,r.hours,r.hours?r.consumption/r.hours:0,r.location?.lat,r.location?.lng,r.location?.accuracy,r.user,r.status,r.note||""])]; const blob=new Blob(["\ufeff"+lines.map(x=>x.map(v=>`"${String(v??"").replaceAll('"','""')}"`).join(";")).join("\n")],{type:"text/csv"}); const a=document.createElement("a"); a.href=URL.createObjectURL(blob); a.download=`relatorio-agua-rural-${from}-a-${to}.csv`; a.click(); URL.revokeObjectURL(a.href); };
  return <div className="stack report-page"><section className="page-head"><div><span className="eyebrow">EVIDÊNCIA OPERACIONAL</span><h2>Relatório de leituras</h2><p>Dossiê de hidrômetro e horímetro para comprovação e fiscalização.</p></div><div className="actions"><button className="outline" onClick={csv}><FileDown/> Excel</button><button className="primary" onClick={()=>window.print()}><FileText/> Gerar evidência PDF</button></div></section><div className="filters"><label>Outorga<select value={grant} onChange={(e)=>setGrant(e.target.value)}><option value="todos">Todas as outorgas</option>{data.grants.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select></label><label>Data inicial<input type="date" value={from} max={to} onChange={(e)=>setFrom(e.target.value)}/></label><label>Data final<input type="date" value={to} min={from} onChange={(e)=>setTo(e.target.value)}/></label></div><section className="evidence-header"><div className="evidence-brand"><img src="/agua-rural-logo.png" alt="Água Rural"/><div><span>DOCUMENTO DE EVIDÊNCIA</span><strong>Controle de captação e funcionamento</strong><small>Emitido em {new Date().toLocaleString("pt-BR")}</small></div></div><div className="evidence-data"><div><span>Área / equipamento</span><strong>{selectedGrant?.name||"Todas as outorgas"}</strong><small>{selectedProperty?.name||`${data.grants.length} outorgas consolidadas`}</small></div><div><span>Número da outorga</span><strong>{selectedGrant?.number||"Relatório consolidado"}</strong><small>{selectedGrant?`Validade: ${brDate(selectedGrant.validity)}`:"Selecione uma outorga para identificação individual"}</small></div><div><span>Período comprovado</span><strong>{from&&to?`${brDate(from)} a ${brDate(to)}`:"Período completo"}</strong><small>{rows.length} registros incluídos</small></div><div><span>Comprovantes fotográficos</span><strong>{proofCount}/{rows.length} completos</strong><small>{proofCount===rows.length&&rows.length?"Documentação completa":"Existem registros sem as duas fotos"}</small></div>{selectedGrant&&<><div><span>Vazão autorizada</span><strong>{fmt(selectedGrant.flow)} m³/h</strong><small>Ponto: {selectedGrant.point}</small></div><div><span>Volume autorizado</span><strong>{fmt(selectedGrant.volume,0)} m³</strong><small>Área cadastrada: {fmt(selectedGrant.area)} ha</small></div></>}</div></section><div className="metrics"><Metric icon={Droplets} tone="cyan" label="Consumo acumulado" value={`${fmt(water,0)} m³`} note={`${rows.length} registros no período`}/><Metric icon={Clock3} tone="amber" label="Horas acumuladas" value={`${fmt(hours)} h`} note="Funcionamento total"/><Metric icon={Gauge} tone="green" label="Vazão média histórica" value={`${fmt(hours?water/hours:0)} m³/h`} note="Média do período"/></div><HistoricalCharts rows={rows}/><section className="panel table-panel report-records"><div className="panel-title"><div><h3>Registros de leitura</h3><p>{from&&to?`${rows.length} registros · ${brDate(from)} a ${brDate(to)}`:"Todos os registros incluídos"}</p></div></div><table><thead><tr><th>Data e outorga</th><th>Hidrômetro</th><th>Consumo</th><th>Horímetro</th><th>Horas</th><th>Vazão média</th><th>Cultura</th><th>Responsável</th><th>Status</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><strong>{brDate(r.date)}</strong><span>{data.grants.find(g=>g.id===r.grantId)?.name}</span></td><td><strong>{fmt(r.waterNow,0)} m³</strong><span>Anterior: {fmt(r.waterPrev,0)} m³</span></td><td><b className="water">+{fmt(r.consumption,0)} m³</b></td><td><strong>{fmt(r.hourNow)} h</strong><span>Anterior: {fmt(r.hourPrev)} h</span></td><td>{fmt(r.hours)} h</td><td>{fmt(r.hours?r.consumption/r.hours:0)} m³/h</td><td><strong>{r.culture||"Não informada"}</strong></td><td><strong>{r.user||"Não informado"}</strong></td><td><Status value={r.status}/></td></tr>)}</tbody></table>{!rows.length&&<div className="empty-report">Nenhuma leitura encontrada no período selecionado.</div>}</section><section className="photo-annex"><div className="annex-title"><div><span>ANEXO I</span><h3>Comprovantes fotográficos das leituras</h3><p>{photoRows.length} registros com imagens vinculadas</p></div><Camera/></div>{photoRows.length?<div className="annex-grid">{photoRows.map(r=>{const grantName=data.grants.find(g=>g.id===r.grantId)?.name;return <article className="annex-record" key={`photo-${r.id}`}><header><div><strong>{grantName}</strong><span>{brDate(r.date)} · {r.user}</span></div><small>ID {r.id}</small></header><div className="annex-photos"><figure>{r.photos?.water?<img src={r.photos.water} alt={`Hidrômetro de ${grantName}`}/>:<div className="missing-photo"><Camera/>Foto não disponível</div>}<figcaption><strong>Hidrômetro · {fmt(r.waterNow,0)} m³</strong><span>Consumo calculado: {fmt(r.consumption,0)} m³</span></figcaption></figure><figure>{r.photos?.hour?<img src={r.photos.hour} alt={`Horímetro de ${grantName}`}/>:<div className="missing-photo"><Camera/>Foto não disponível</div>}<figcaption><strong>Horímetro · {fmt(r.hourNow)} h</strong><span>Funcionamento: {fmt(r.hours)} h</span></figcaption></figure></div></article>})}</div>:<div className="annex-empty"><Camera/><strong>Nenhuma foto disponível neste período</strong><span>Os registros de demonstração não possuem imagens. Novas leituras exigem as duas fotos.</span></div>}</section><section className="evidence-declaration"><ShieldCheck/><div><strong>Declaração de integridade dos registros</strong><p>Este documento consolida as leituras registradas no Água Rural no período informado. Os cálculos de consumo, horas de funcionamento e vazão média são derivados da diferença entre leituras consecutivas.</p></div><span>Responsável pela emissão<br/><b>{userName} · Administrador</b></span></section></div>;
}

function HistoricalCharts({rows}){
  const daily=[...rows].sort((a,b)=>a.date.localeCompare(b.date)).slice(-7),months=Object.values(rows.reduce((acc,r)=>{const k=r.date.slice(0,7);acc[k]??={date:k,consumption:0};acc[k].consumption+=r.consumption;return acc},{}));
  return <section className="chart-grid"><MiniChart title="Consumo diário" unit="m³" rows={daily} value={r=>r.consumption}/><MiniChart title="Horas de funcionamento" unit="h" rows={daily} value={r=>r.hours}/><MiniChart title="Consumo acumulado" unit="m³/mês" rows={months} value={r=>r.consumption}/></section>
}
function MiniChart({title,unit,rows,value}){const vals=rows.map(value),max=Math.max(...vals,1),points=vals.map((v,i)=>`${14+(i*(212/Math.max(vals.length-1,1)))},${82-(v/max)*58}`).join(" ");return <article className="panel mini-chart"><header><div><h3>{title}</h3><span>{unit}</span></div><strong>{fmt(vals.reduce((s,v)=>s+v,0),unit==="h"?1:0)} {unit.split("/")[0]}</strong></header><svg viewBox="0 0 240 96" role="img" aria-label={`${title}: ${vals.map(v=>fmt(v)).join(", ")}`}><line x1="14" y1="82" x2="226" y2="82"/><polyline points={points}/>{vals.map((v,i)=><circle key={i} cx={14+(i*(212/Math.max(vals.length-1,1)))} cy={82-(v/max)*58} r="3"/>)}</svg><footer><span>{rows[0]?.date||"Sem dados"}</span><span>{rows.at(-1)?.date||""}</span></footer></article>}

function OperatorReadingModal({data,initialId,userName,onClose,onSave}) {
  const [grantId,setGrantId]=useState(initialId||data.grants[0]?.id),[step,setStep]=useState(0),[culture,setCulture]=useState(""),[location,setLocation]=useState(null),[locating,setLocating]=useState(false),[water,setWater]=useState(""),[hours,setHours]=useState(""),[photos,setPhotos]=useState({water:null,hour:null}),[scans,setScans]=useState({water:null,hour:null}),[note,setNote]=useState(""),[error,setError]=useState("");
  const grant=data.grants.find((item)=>item.id===grantId),property=data.properties.find((item)=>item.id===grant?.propertyId),last=lastReading(data,grantId),prevW=last?.waterNow||0,prevH=last?.hourNow||0;
  const consumption=water===""||!last?0:Number(water)-prevW,operating=hours===""||!last?0:Number(hours)-prevH,averageFlow=operating>0?consumption/operating:0,blade=grant?.area?consumption/(Number(grant.area)*10):0;
  const grantReadings=data.readings.filter((item)=>item.grantId===grantId),average=grantReadings.reduce((sum,item)=>sum+item.consumption,0)/Math.max(grantReadings.length,1),divergent=water!==""&&hours!==""&&((average>0&&(consumption>average*1.25||consumption<average*.5))||(consumption>0&&operating===0)||(operating>0&&consumption===0));
  const cultures=["Soja","Milho","Feijão","Sorgo","Aveia","Trigo","Café","Batata","Outra"];
  const steps=["Preparar","Hidrômetro","Horímetro","Confirmar"];
  useEffect(()=>{setWater("");setHours("");setPhotos({water:null,hour:null});setScans({water:null,hour:null});setError("")},[grantId]);
  const captureLocation=()=>{if(!navigator.geolocation)return setError("Este celular não oferece localização.");setLocating(true);navigator.geolocation.getCurrentPosition((position)=>{setLocation({lat:position.coords.latitude,lng:position.coords.longitude,accuracy:position.coords.accuracy,capturedAt:new Date().toISOString()});setLocating(false);setError("")},()=>{setLocating(false);setError("Autorize a localização do celular e tente novamente.")},{enableHighAccuracy:true,timeout:15000,maximumAge:0})};
  const selectPhoto=async(type,event)=>{const file=event.target.files?.[0];if(!file)return;setScans((state)=>({...state,[type]:{status:"reading"}}));try{const [storedImage,ocrImage]=await Promise.all([photoData(file),ocrPhotoData(file)]);setPhotos((state)=>({...state,[type]:storedImage}));const previous=type==="water"?prevW:prevH;try{const detected=await readMeterPhoto(ocrImage,previous);(type==="water"?setWater:setHours)(detected.value);setScans((state)=>({...state,[type]:{status:"success",...detected}}));setError("")}catch{setScans((state)=>({...state,[type]:{status:"failed"}}));setError("Não consegui ler o número. Confira a ampliação e digite a leitura abaixo.")}}catch{setScans((state)=>({...state,[type]:{status:"failed"}}));setError("Não foi possível usar essa foto. Tente novamente.")}};
  const next=()=>{setError("");if(step===0&&!culture)return setError("Escolha a cultura para continuar.");if(step===0&&!location)return setError("Toque em Confirmar localização para continuar.");if(step===1&&(!photos.water||water===""))return setError("Tire a foto do hidrômetro e confira a leitura.");if(step===1&&consumption<0)return setError("A leitura do hidrômetro não pode ser menor que a anterior.");if(step===2&&(!photos.hour||hours===""))return setError("Tire a foto do horímetro e confira a leitura.");if(step===2&&operating<0)return setError("A leitura do horímetro não pode ser menor que a anterior.");setStep((value)=>Math.min(3,value+1))};
  const submit=()=>{if(data.readings.some((item)=>item.grantId===grantId&&item.date===today()))return setError("Já existe uma leitura para esta outorga hoje.");onSave({id:crypto.randomUUID(),grantId,date:today(),waterPrev:last?prevW:Number(water),waterNow:Number(water),consumption,hourPrev:last?prevH:Number(hours),hourNow:Number(hours),hours:operating,averageFlow,blade,photos,location,culture,user:userName,note,status:divergent?"divergente":"concluida"})};
  return <div className="modal-backdrop"><div className="modal reading-wizard operator-wizard"><header><div><span className="eyebrow">LEITURA RÁPIDA · {step+1} DE 4</span><h2>{steps[step]}</h2></div><button className="icon-btn" onClick={onClose} aria-label="Fechar registro"><X/></button></header><div className="operator-progress">{steps.map((label,index)=><div key={label} className={index<step?"done":index===step?"active":""}><span>{index<step?<CheckCircle2/>:index+1}</span><strong>{label}</strong></div>)}</div><div className="modal-body wizard-body">
    {step===0&&<section className="wizard-screen operator-prepare"><div className="operator-equipment"><div className="equip"><Droplets/></div><div><span>EQUIPAMENTO</span><strong>{grant?.name}</strong><small>{property?.name}</small></div></div><label className="field">Se precisar trocar o equipamento<select value={grantId} onChange={(event)=>setGrantId(event.target.value)}>{data.grants.filter((item)=>item.status==="ativa").map((item)=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><div className="operator-question"><strong>Qual cultura está usando a água?</strong><div className="culture-options">{cultures.map((item)=><button type="button" key={item} className={culture===item?"selected":""} onClick={()=>setCulture(item)}>{culture===item&&<CheckCircle2/>}{item}</button>)}</div></div><div className={location?"location-capture captured":"location-capture"}><MapPin/><div><strong>{location?"Localização confirmada":"Confirme onde você está"}</strong><span>{location?`GPS registrado · precisão ${fmt(location.accuracy,0)} m`:"Necessário para comprovar a leitura."}</span></div><button type="button" onClick={captureLocation} disabled={locating}>{locating?"LOCALIZANDO...":location?"ATUALIZAR":"CONFIRMAR LOCALIZAÇÃO"}</button></div></section>}
    {step===1&&<section className="wizard-screen"><div className="operator-instruction"><span>1</span><div><strong>Tire uma foto de perto</strong><p>Deixe somente os números do hidrômetro dentro da foto.</p></div></div><ReadingBlock title="Hidrômetro" icon={Droplets} previous={prevW} previousDate={last?.date} unit="m³" value={water} setValue={setWater} result={consumption} resultLabel="Consumo calculado" photo={photos.water} scan={scans.water} setPhoto={(event)=>selectPhoto("water",event)}/></section>}
    {step===2&&<section className="wizard-screen"><div className="operator-instruction"><span>2</span><div><strong>Agora fotografe o horímetro</strong><p>Centralize os números e evite reflexos no visor.</p></div></div><ReadingBlock title="Horímetro" icon={Clock3} previous={prevH} previousDate={last?.date} unit="h" value={hours} setValue={setHours} result={operating} resultLabel="Horas calculadas" photo={photos.hour} scan={scans.hour} setPhoto={(event)=>selectPhoto("hour",event)}/></section>}
    {step===3&&<section className="wizard-screen"><div className="operator-success"><CheckCircle2/><div><strong>Leitura pronta para salvar</strong><span>Confira somente os dois números abaixo.</span></div></div><div className="operator-review"><article><span>HIDRÔMETRO</span><strong>{fmt(water)} m³</strong><small>Consumo: +{fmt(consumption)} m³</small></article><article><span>HORÍMETRO</span><strong>{fmt(hours)} h</strong><small>Funcionamento: +{fmt(operating)} h</small></article></div><div className="operator-summary"><div><span>Equipamento</span><strong>{grant?.name}</strong></div><div><span>Cultura</span><strong>{culture}</strong></div><div><span>Vazão média</span><strong>{fmt(averageFlow)} m³/h</strong></div><div><span>GPS e fotos</span><strong>Confirmados</strong></div></div>{divergent&&<div className="warning"><AlertTriangle/><span><strong>Valor fora do padrão</strong>A leitura será salva para conferência do administrador.</span></div>}<label className="field">Observação, se necessário<textarea rows="2" value={note} onChange={(event)=>setNote(event.target.value)} placeholder="Opcional"/></label></section>}
    {error&&<div className="form-error"><AlertTriangle/>{error}</div>}
  </div><footer className="wizard-actions"><button className="ghost" onClick={()=>step===0?onClose():(setError(""),setStep((value)=>value-1))}>{step===0?"Cancelar":"Voltar"}</button>{step<3?<button className="primary" onClick={next}>CONTINUAR <ChevronRight/></button>:<button className="primary save-reading" onClick={submit}><CheckCircle2/> SALVAR LEITURA</button>}</footer></div></div>;
}

function ReadingModal({ data, initialId, userName, onClose, onSave }) {
  const [grantId,setGrantId]=useState(initialId||data.grants[0].id); const grant=data.grants.find(g=>g.id===grantId), last=lastReading(data,grantId); const prevW=last?.waterNow||grant?.waterInitial||0, prevH=last?.hourNow||grant?.hourInitial||0;
  const [step,setStep]=useState(0); const [water,setWater]=useState(""); const [hours,setHours]=useState(""); const [culture,setCulture]=useState(""); const [photos,setPhotos]=useState({water:null,hour:null}); const [scans,setScans]=useState({water:null,hour:null}); const [location,setLocation]=useState(null); const [locating,setLocating]=useState(false); const [note,setNote]=useState(""); const [error,setError]=useState("");
  useEffect(()=>{setWater("");setHours("");setPhotos({water:null,hour:null});setScans({water:null,hour:null});setError("")},[grantId]); const consumption=water===""?0:Number(water)-prevW, operating=hours===""?0:Number(hours)-prevH, averageFlow=operating>0?consumption/operating:0, blade=grant?.area?consumption/(Number(grant.area)*10):0; const grantReadings=data.readings.filter(r=>r.grantId===grantId), avg=grantReadings.reduce((s,r)=>s+r.consumption,0)/Math.max(grantReadings.length,1); const hasBothReadings=water!==""&&hours!=="", divergent=hasBothReadings&&((avg>0&&(consumption>avg*1.25||consumption<avg*.5))||(consumption>0&&operating===0)||(operating>0&&consumption===0));
  const selectPhoto=async(type,event)=>{const file=event.target.files?.[0];if(!file)return;setScans(s=>({...s,[type]:{status:"reading"}}));try{const value=await photoData(file);setPhotos(p=>({...p,[type]:value}));const previous=type==="water"?prevW:prevH;try{const detected=await readMeterPhoto(value,previous);(type==="water"?setWater:setHours)(detected.value);setScans(s=>({...s,[type]:{status:"success",...detected}}));setError("")}catch{setScans(s=>({...s,[type]:{status:"failed"}}));setError("A foto foi salva, mas o número não ficou legível. Digite a leitura ou tire outra foto.")}}catch{setScans(s=>({...s,[type]:{status:"failed"}}));setError("Não foi possível processar a foto. Tente novamente.")}};
  const captureLocation=()=>{if(!navigator.geolocation)return setError("Este dispositivo não oferece localização.");setLocating(true);navigator.geolocation.getCurrentPosition(p=>{setLocation({lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy,capturedAt:new Date().toISOString()});setLocating(false);setError("")},()=>{setLocating(false);setError("Não foi possível obter a localização. Autorize o GPS e tente novamente.")},{enableHighAccuracy:true,timeout:15000,maximumAge:0})};
  const submit=()=>{ if(!culture) return setError("Selecione a cultura que está utilizando a água."); if(!photos.water||!photos.hour) return setError("Anexe as duas fotos para continuar."); if(water===""||hours==="") return setError("Informe as duas leituras."); if(consumption<0||operating<0) return setError("A leitura atual não pode ser menor que a anterior."); if(data.readings.some(r=>r.grantId===grantId&&r.date===today())) return setError("Já existe uma leitura para esta outorga hoje."); onSave({id:crypto.randomUUID(),grantId,date:today(),waterPrev:prevW,waterNow:Number(water),consumption,hourPrev:prevH,hourNow:Number(hours),hours:operating,averageFlow,blade,photos,location,culture,user:userName,note,status:divergent?"divergente":"concluida"}); };
  const steps=["Identificação","Localização","Hidrômetro","Horímetro","Revisão"];
  const next=()=>{setError("");if(step===0&&!culture)return setError("Selecione a cultura para continuar.");if(step===1&&!location)return setError("Capture a localização para continuar.");if(step===2&&(!photos.water||water===""))return setError("Tire a foto e informe a leitura do hidrômetro.");if(step===2&&consumption<0)return setError("A leitura não pode ser menor que a anterior.");if(step===3&&(!photos.hour||hours===""))return setError("Tire a foto e informe a leitura do horímetro.");if(step===3&&operating<0)return setError("A leitura não pode ser menor que a anterior.");setStep(s=>Math.min(s+1,4));};
  return <div className="modal-backdrop"><div className="modal reading-wizard"><header><div><span className="eyebrow">REGISTRO GUIADO · ETAPA {step+1} DE 5</span><h2>{steps[step]}</h2></div><button className="icon-btn" onClick={onClose} aria-label="Fechar registro"><X/></button></header><div className="wizard-progress" aria-label={`Etapa ${step+1} de 5`}>{steps.map((label,index)=><div key={label} className={index<step?"done":index===step?"active":""}><span>{index<step?<CheckCircle2/>:index+1}</span><small>{label}</small></div>)}</div><div className="modal-body wizard-body">
    {step===0&&<section className="wizard-screen"><div className="step-intro"><strong>Qual equipamento será lido?</strong><p>Confira a outorga e informe a cultura que está usando a água.</p></div><div className="reading-context"><label className="field">Outorga<select value={grantId} onChange={e=>setGrantId(e.target.value)}>{data.grants.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select></label><label className="field">Cultura utilizando a água<select value={culture} onChange={e=>setCulture(e.target.value)}><option value="">Selecione a cultura</option><option>Soja</option><option>Milho</option><option>Feijão</option><option>Algodão</option><option>Café</option><option>Cana-de-açúcar</option><option>Pastagem</option><option>Hortaliças</option><option>Outra cultura</option></select></label></div><div className="auto-info"><Clock3/> Data, horário e responsável serão registrados automaticamente.</div></section>}
    {step===1&&<section className="wizard-screen"><div className="step-intro"><strong>Registre o local da leitura</strong><p>Fique próximo ao equipamento e toque no botão abaixo.</p></div><div className={location?"location-capture captured":"location-capture"}><MapPin/><div><strong>{location?"Localização capturada com sucesso":"GPS ainda não capturado"}</strong><span>{location?`${location.lat.toFixed(6)}, ${location.lng.toFixed(6)} · precisão ${fmt(location.accuracy,0)} m`:"A localização comprova onde a medição foi realizada."}</span></div><button type="button" onClick={captureLocation} disabled={locating}>{locating?"LOCALIZANDO...":location?"ATUALIZAR LOCALIZAÇÃO":"CAPTURAR LOCALIZAÇÃO"}</button></div></section>}
    {step===2&&<section className="wizard-screen"><div className="step-intro"><strong>Fotografe o hidrômetro</strong><p>Centralize os números. O sistema fará a leitura e preencherá o campo automaticamente.</p></div><ReadingBlock title="Hidrômetro" icon={Droplets} previous={prevW} previousDate={last?.date} unit="m³" value={water} setValue={setWater} result={consumption} resultLabel="Consumo calculado" photo={photos.water} scan={scans.water} setPhoto={e=>selectPhoto("water",e)}/></section>}
    {step===3&&<section className="wizard-screen"><div className="step-intro"><strong>Fotografe o horímetro</strong><p>Centralize os números. O sistema fará a leitura e preencherá o campo automaticamente.</p></div><ReadingBlock title="Horímetro" icon={Clock3} previous={prevH} previousDate={last?.date} unit="h" value={hours} setValue={setHours} result={operating} resultLabel="Funcionamento calculado" photo={photos.hour} scan={scans.hour} setPhoto={e=>selectPhoto("hour",e)}/></section>}
    {step===4&&<section className="wizard-screen"><div className="step-intro"><strong>Confira antes de salvar</strong><p>Se algum dado estiver incorreto, use o botão Voltar para corrigir.</p></div><div className="review-card"><div><span>Outorga</span><strong>{grant?.name}</strong></div><div><span>Cultura</span><strong>{culture}</strong></div><div><span>Hidrômetro</span><strong>{fmt(water)} m³</strong><small>Consumo: {fmt(consumption)} m³</small></div><div><span>Horímetro</span><strong>{fmt(hours)} h</strong><small>Funcionamento: {fmt(operating)} h</small></div><div><span>Localização</span><strong>{location?"GPS confirmado":"Não capturada"}</strong></div><div><span>Fotos</span><strong>{photos.water&&photos.hour?"2 fotos anexadas":"Fotos pendentes"}</strong></div></div><div className="calculated-summary"><div><span>Vazão média</span><strong>{fmt(averageFlow)} m³/h</strong></div><div><span>Lâmina aplicada</span><strong>{grant?.area?`${fmt(blade,2)} mm`:"Área não cadastrada"}</strong></div></div>{divergent&&<div className="warning"><AlertTriangle/><span><strong>Possível divergência</strong>Esta medição ficará aguardando conferência.</span></div>}<label className="field">Observação (opcional)<textarea rows="3" value={note} onChange={e=>setNote(e.target.value)} placeholder="Digite alguma informação importante"/></label></section>}
    {error&&<div className="form-error"><AlertTriangle/>{error}</div>}
  </div><footer className="wizard-actions"><button className="ghost" onClick={()=>step===0?onClose():(setError(""),setStep(s=>s-1))}>{step===0?"Cancelar":"Voltar"}</button>{step<4?<button className="primary" onClick={next}>CONTINUAR <ChevronRight/></button>:<button className="primary save-reading" onClick={submit}><CheckCircle2/> CONFIRMAR E SALVAR</button>}</footer></div></div>;
}
function ReadingBlock({title,icon:Icon,previous,previousDate,unit,value,setValue,result,resultLabel,photo,scan,setPhoto}) { return <section className="reading-block"><div className="block-head"><div className="equip"><Icon/></div><div><h3>{title}</h3><span>Última leitura: <strong>{fmt(previous)} {unit}</strong>{previousDate&&` · ${brDate(previousDate)}`}</span></div></div><div className="reading-inputs"><label className={photo?"photo-button done":"photo-button"}>{photo?<img src={photo} alt="Prévia da foto"/>:<Camera/>}<span>{photo?"Tirar outra foto":"Tirar foto"}<small>{photo?"Toque para substituir":"Obrigatória"}</small></span><input type="file" accept="image/*" capture="environment" onChange={setPhoto}/></label><label className="field">Leitura atual ({unit})<input type="number" inputMode="decimal" step="0.1" value={value} onChange={e=>setValue(e.target.value)} placeholder={`Maior ou igual a ${previous}`}/></label><div className={result<0?"calc invalid":"calc"}><span>{resultLabel}</span><strong>{fmt(Math.max(result,0))} {unit}</strong></div></div>{scan&&<div className={`scan-status ${scan.status}`}>{scan.status==="reading"?<><span className="scan-spinner"/><div><strong>Lendo os números da foto...</strong><small>Isso pode levar alguns segundos.</small></div></>:scan.status==="success"?<><CheckCircle2/><div><strong>Leitura preenchida automaticamente: {fmt(scan.value)} {unit}</strong><small>Confira o número antes de continuar{scan.confidence?` · confiança ${scan.confidence}%`:""}.</small></div></>:<><AlertTriangle/><div><strong>Não foi possível reconhecer com segurança</strong><small>Digite o número acima ou tire outra foto mais próxima.</small></div></>}</div>}</section>; }

function GrantModal({data,onClose,onSave}) { const [form,setForm]=useState({name:"",number:"",propertyId:data.properties[0]?.id||"",source:"Poço tubular",flow:"",area:"",volume:"",validity:"",waterInitial:"",hourInitial:"",point:""}); const update=(k,v)=>setForm(f=>({...f,[k]:v})); const submit=()=>{if(!form.name||!form.number||!form.propertyId)return; onSave({...form,id:crypto.randomUUID(),status:"ativa",flow:Number(form.flow),area:Number(form.area),volume:Number(form.volume),waterInitial:Number(form.waterInitial),hourInitial:Number(form.hourInitial)},null)}; return <div className="modal-backdrop"><div className="modal"><header><div><span className="eyebrow">CADASTRO</span><h2>Nova outorga</h2></div><button className="icon-btn" onClick={onClose}><X/></button></header><div className="modal-body form-grid"><label className="field full">Nome ou identificação<input value={form.name} onChange={e=>update("name",e.target.value)} placeholder="Ex.: Poço Artesiano 02"/></label><label className="field">Número da outorga<input value={form.number} onChange={e=>update("number",e.target.value)}/></label><label className="field">Propriedade<select value={form.propertyId} onChange={e=>update("propertyId",e.target.value)}>{data.properties.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label className="field">Ponto de captação<input value={form.point} onChange={e=>update("point",e.target.value)}/></label><label className="field">Fonte de água<select value={form.source} onChange={e=>update("source",e.target.value)}><option>Poço tubular</option><option>Água superficial</option><option>Nascente</option></select></label><label className="field">Vazão autorizada (m³/h)<input type="number" value={form.flow} onChange={e=>update("flow",e.target.value)}/></label><label className="field">Área irrigada (ha)<input type="number" value={form.area} onChange={e=>update("area",e.target.value)}/></label><label className="field">Volume autorizado (m³)<input type="number" value={form.volume} onChange={e=>update("volume",e.target.value)}/></label><label className="field">Data de validade<input type="date" value={form.validity} onChange={e=>update("validity",e.target.value)}/></label><label className="field">Leitura inicial hidrômetro<input type="number" value={form.waterInitial} onChange={e=>update("waterInitial",e.target.value)}/></label><label className="field">Leitura inicial horímetro<input type="number" value={form.hourInitial} onChange={e=>update("hourInitial",e.target.value)}/></label></div><footer><button className="ghost" onClick={onClose}>Cancelar</button><button className="primary" onClick={submit}>Salvar outorga</button></footer></div></div>; }
